package counter

import "unicode"

// LineCounter counts the number of lines, letters and total characters
// across all strings added to it via AddString.
type LineCounter struct {
	newlines   int
	characters int
	letters    int
	lastChar   rune
}

// AddString adds the string s to the counter's running totals.
func (c *LineCounter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.characters++
	}
}

// Lines reports the total number of lines. The input has zero lines if it
// contains no characters, otherwise one line per newline plus one more if
// the last character is not a newline.
func (c LineCounter) Lines() int {
	switch {
	case c.characters == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

// Letters reports the total number of Unicode letters.
func (c LineCounter) Letters() int { return c.letters }

// Characters reports the total number of characters (runes).
func (c LineCounter) Characters() int { return c.characters }

var _ Counter = (*LineCounter)(nil)

